function integrate(key,t,stepFn,reset){if(key!==simKey||t<simT-.001){reset();simT=0;simKey=key;}const dt=.025;while(simT<t){simT=Math.min(t,simT+dt);stepFn(simT);}}
const cam={target:new T.Vector3(),dir:new T.Vector3(0,.08,1),dist:3};
function camOn(P,s,dist,dir=[.12,.1,1]){at(P,s,cam.target);cam.dist=dist;cam.dir.set(...dir).normalize();}
