const active=on&&t>=8.5&&t<19,dirn=dev==='aspirex'?1:1;parts.forEach((m,k)=>{m.visible=false;if(!active)return;const u=((t*1.4+k/parts.length)%1);if(u>.85)return;const ss=s+3+(1-u)*6,i=Math.max(0,Math.min(P.N,Math.round(ss))),a=k*2.4;at(P,ss,m.position);m.position.addScaledVector(P.n[i],Math.cos(a)*P.R[i]*.7*(1-u)).addScaledVector(P.b[i],Math.sin(a)*P.R[i]*.7*(1-u));m.scale.setScalar(.004+.003*hash(k,1));m.material.color.setHex(0x6b1e14);m.material.opacity=.95;m.visible=true;});
